import type {
  AttachmentId,
  IsoTimestamp,
  IssueId,
  LabelId,
  ProjectId,
  SoftDeletable,
  TenantScoped,
  Timestamps,
  UserId,
} from "./common";

export type IssueStatus =
  | "backlog"
  | "todo"
  | "in_progress"
  | "in_review"
  | "done"
  | "canceled";

export const ISSUE_STATUSES: readonly IssueStatus[] = [
  "backlog",
  "todo",
  "in_progress",
  "in_review",
  "done",
  "canceled",
];

/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

export type IssuePriority = "none" | "low" | "medium" | "high" | "urgent";

export const ISSUE_PRIORITIES: readonly IssuePriority[] = [
  "none",
  "low",
  "medium",
  "high",
  "urgent",
];

export interface Issue extends Timestamps, TenantScoped, SoftDeletable {
  readonly id: IssueId;
  readonly projectId: ProjectId;
  readonly number: number;
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly authorId: UserId;
  readonly assigneeId: UserId | null;
  readonly parentId: IssueId | null;
  readonly estimate: number | null;
  readonly dueAt: IsoTimestamp | null;
  readonly startedAt: IsoTimestamp | null;
  readonly completedAt: IsoTimestamp | null;
  readonly labelIds: readonly LabelId[];
}

export interface IssueLabel extends TenantScoped {
  readonly id: LabelId;
  readonly name: string;
  readonly color: string;
  readonly description: string | null;
}

export interface IssueAttachment extends Timestamps, TenantScoped {
  readonly id: AttachmentId;
  readonly issueId: IssueId;
  readonly filename: string;
  readonly contentType: string;
  readonly sizeBytes: number;
  readonly uploadedBy: UserId;
}

/** Filter accepted by the issue repository, service layer and list UI alike. */
export interface IssueFilter {
  readonly projectId?: ProjectId;
  readonly status?: readonly IssueStatus[];
  readonly priority?: readonly IssuePriority[];
  readonly assigneeId?: UserId | null;
  readonly authorId?: UserId;
  readonly labelIds?: readonly LabelId[];
  readonly query?: string;
  readonly dueBefore?: IsoTimestamp;
  readonly includeArchived?: boolean;
}

export interface IssueWithRelations {
  readonly issue: Issue;
  readonly labels: readonly IssueLabel[];
  readonly commentCount: number;
  readonly attachmentCount: number;
}

/** One column of the kanban board; the board is an ordered list of these. */
export interface IssueBoardColumn {
  readonly status: IssueStatus;
  readonly issues: readonly Issue[];
  readonly total: number;
}
import type {
  IsoTimestamp,
  NotificationId,
  TenantScoped,
  Timestamps,
  UserId,
} from "./common";

export type NotificationKind =
  | "issue_assigned"
  | "issue_status_changed"
  | "issue_due_soon"
  | "issue_overdue"
  | "comment_created"
  | "comment_mention"
  | "member_invited"
  | "member_joined"
  | "project_archived"
  | "plan_limit_reached"
  | "digest_ready";

export type NotificationChannel = "in_app" | "email" | "webhook";

export interface Notification extends Timestamps, TenantScoped {
  readonly id: NotificationId;
  readonly recipientId: UserId;
  readonly kind: NotificationKind;
  readonly title: string;
  readonly body: string;
  readonly href: string;
  readonly actorId: UserId | null;
  readonly readAt: IsoTimestamp | null;
  readonly channels: readonly NotificationChannel[];
}

/** Per-user delivery matrix; the fan-out consults this before every send. */
export interface NotificationPreference extends TenantScoped {
  readonly userId: UserId;
  readonly kind: NotificationKind;
  readonly inApp: boolean;
  readonly email: boolean;
  readonly digestOnly: boolean;
}

/** One item queued for the daily digest email. */
export interface DigestEntry {
  readonly notificationId: NotificationId;
  readonly kind: NotificationKind;
  readonly title: string;
  readonly href: string;
  readonly occurredAt: IsoTimestamp;
}

export interface DigestBundle extends TenantScoped {
  readonly recipientId: UserId;
  readonly entries: readonly DigestEntry[];
  readonly windowStart: IsoTimestamp;
  readonly windowEnd: IsoTimestamp;
}
import { z } from "zod";
import type { NotificationKind } from "@/types/notification";
import {
  notificationIdSchema,
  orgIdSchema,
  pageRequestSchema,
  userIdSchema,
} from "./common";

export const notificationKindSchema = z.enum([
  "issue_assigned",
  "issue_status_changed",
  "issue_due_soon",
  "issue_overdue",
  "comment_created",
  "comment_mention",
  "member_invited",
  "member_joined",
  "project_archived",
  "plan_limit_reached",
  "digest_ready",
]);

export const notificationChannelSchema = z.enum(["in_app", "email", "webhook"]);

export const markNotificationReadSchema = z.object({
  orgId: orgIdSchema,
  notificationId: notificationIdSchema,
});

export const markAllNotificationsReadSchema = z.object({
  orgId: orgIdSchema,
});

export const listNotificationsSchema = z
  .object({
    orgId: orgIdSchema,
    recipientId: userIdSchema,
    unreadOnly: z.boolean().default(false),
    kind: z.array(notificationKindSchema).optional(),
  })
  .extend(pageRequestSchema.shape);

export const updateNotificationPreferenceSchema = z.object({
  orgId: orgIdSchema,
  userId: userIdSchema,
  kind: notificationKindSchema,
  inApp: z.boolean(),
  email: z.boolean(),
  digestOnly: z.boolean(),
});

const _kindParity: NotificationKind = "comment_mention" satisfies z.infer<
  typeof notificationKindSchema
>;
void _kindParity;

export type MarkNotificationReadInput = z.infer<
  typeof markNotificationReadSchema
>;
export type ListNotificationsInput = z.infer<typeof listNotificationsSchema>;
export type UpdateNotificationPreferenceInput = z.infer<
  typeof updateNotificationPreferenceSchema
>;
import { index, integer, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import {
  idColumn,
  softDeleteColumns,
  tenantColumns,
  timestampColumns,
} from "./_shared";

export const issues = sqliteTable(
  "issues",
  {
    id: idColumn(),
    ...tenantColumns,
    projectId: text("project_id").notNull(),
    number: integer("number").notNull(),
    title: text("title").notNull(),
    description: text("description"),
    status: text("status", {
      enum: ["backlog", "todo", "in_progress", "in_review", "done", "canceled"],
    })
      .notNull()
      .default("backlog"),
    priority: text("priority", {
      enum: ["none", "low", "medium", "high", "urgent"],
    })
      .notNull()
      .default("none"),
    authorId: text("author_id").notNull(),
    assigneeId: text("assignee_id"),
    parentId: text("parent_id"),
    estimate: integer("estimate"),
    dueAt: text("due_at"),
    startedAt: text("started_at"),
    completedAt: text("completed_at"),
    ...timestampColumns,
    ...softDeleteColumns,
  },
  (table) => [
    uniqueIndex("issues_project_number_idx").on(table.projectId, table.number),
    index("issues_org_status_idx").on(table.orgId, table.status),
    index("issues_org_assignee_idx").on(table.orgId, table.assigneeId),
    index("issues_org_archived_idx").on(table.orgId, table.archivedAt),
    index("issues_org_due_idx").on(table.orgId, table.dueAt),
  ],
);

export const labels = sqliteTable(
  "labels",
  {
    id: idColumn(),
    ...tenantColumns,
    name: text("name").notNull(),
    color: text("color").notNull().default("#94a3b8"),
    description: text("description"),
    ...timestampColumns,
  },
  (table) => [uniqueIndex("labels_org_name_idx").on(table.orgId, table.name)],
);

export const issueLabels = sqliteTable(
  "issue_labels",
  {
    ...tenantColumns,
    issueId: text("issue_id").notNull(),
    labelId: text("label_id").notNull(),
  },
  (table) => [
    uniqueIndex("issue_labels_pk").on(table.issueId, table.labelId),
    index("issue_labels_org_idx").on(table.orgId),
  ],
);

export const attachments = sqliteTable(
  "attachments",
  {
    id: idColumn(),
    ...tenantColumns,
    issueId: text("issue_id").notNull(),
    filename: text("filename").notNull(),
    contentType: text("content_type").notNull(),
    sizeBytes: integer("size_bytes").notNull(),
    uploadedBy: text("uploaded_by").notNull(),
    ...timestampColumns,
  },
  (table) => [index("attachments_org_issue_idx").on(table.orgId, table.issueId)],
);

export type IssueRow = typeof issues.$inferSelect;
export type NewIssueRow = typeof issues.$inferInsert;
export type LabelRow = typeof labels.$inferSelect;
export type AttachmentRow = typeof attachments.$inferSelect;
import { index, integer, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

const NOTIFICATION_KINDS = [
  "issue_assigned",
  "issue_status_changed",
  "issue_due_soon",
  "issue_overdue",
  "comment_created",
  "comment_mention",
  "member_invited",
  "member_joined",
  "project_archived",
  "plan_limit_reached",
  "digest_ready",
] as const;

export const notifications = sqliteTable(
  "notifications",
  {
    id: idColumn(),
