  `CREATE INDEX IF NOT EXISTS invitations_org_email_idx ON invitations (org_id, email)`,
  `CREATE TABLE IF NOT EXISTS projects (
     id TEXT PRIMARY KEY NOT NULL,
     org_id TEXT NOT NULL,
     name TEXT NOT NULL,
     slug TEXT NOT NULL,
