/**
 * "Blocked by" links between issues of one organization. A row reads
 * "`issue_id` is blocked by `blocker_id`".
 *
 * Must call (do not reimplement): livePredicate, orgPredicate
 */
import { and, asc, eq, inArray, notInArray } from "drizzle-orm";
import { getDb, issueDependencies, issues } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { brandId, toIssue, toIssueDependency } from "./_mappers";
import { compact } from "./_paging";
import type { IssueId, OrgId, ProjectId, UserId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .get();
  return row ? toIssueDependency(row) : null;
}

/** Idempotent: an existing link is returned unchanged, never duplicated. */
export async function insertDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
  createdBy: UserId,
): Promise<IssueDependency> {
  getDb()
    .insert(issueDependencies)
    .values({
      orgId,
      issueId,
      blockerId,
      createdBy,
      createdAt: toIsoTimestamp(new Date()),
    })
    .onConflictDoNothing()
    .run();

  const link = await findDependency(orgId, issueId, blockerId);
  if (!link) throw new Error(`Dependency ${issueId} → ${blockerId} not stored`);
  return link;
}

/** Resolves `true` when a link was removed, `false` when there was none. */
export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const result = getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .run();
  return result.changes > 0;
}

/** Ids of every issue `issueId` is directly blocked by, archived or not. */
export async function listBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ blockerId: issueDependencies.blockerId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
      ),
    )
    .all();
  return rows.map((row) => brandId<IssueId>(row.blockerId));
}

/** Ids of every issue directly blocked by `blockerId`. */
export async function listBlockedIds(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ issueId: issueDependencies.issueId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .all();
  return rows.map((row) => brandId<IssueId>(row.issueId));
}

/**
 * Live blocker issues of `issueId`, by issue number. With `openOnly` the
 * `done` / `canceled` blockers are left out as well.
 */
export async function listBlockerIssues(
  orgId: OrgId,
  issueId: IssueId,
  options: { openOnly?: boolean } = {},
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issueDependencies)
    .innerJoin(
      issues,
      and(
        eq(issues.id, issueDependencies.blockerId),
        orgPredicate(issues.orgId, orgId),
      ),
    )
    .where(
      and(
        ...compact(
          orgPredicate(issueDependencies.orgId, orgId),
          eq(issueDependencies.issueId, issueId),
          livePredicate(issues.archivedAt, {}),
          options.openOnly === true
            ? notInArray(issues.status, [...CLOSED_ISSUE_STATUSES])
            : undefined,
        ),
      ),
    )
    .orderBy(asc(issues.number))
    .all();
  return rows.map((row) => toIssue(row.issue));
}

/** Live, open issues of a project that block at least one other issue. */
export async function listOpenBlockerIdsInProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .selectDistinct({ id: issues.id })
    .from(issues)
    .innerJoin(
      issueDependencies,
      and(
        eq(issueDependencies.blockerId, issues.id),
        orgPredicate(issueDependencies.orgId, orgId),
      ),
    )
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
          notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
        ),
      ),
    )
    .all();
  return rows.map((row) => brandId<IssueId>(row.id));
}

/** Drops every link touching the given issues, e.g. when they are purged. */
export async function deleteDependenciesForIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<number> {
  if (issueIds.length === 0) return 0;
  const ids = [...issueIds];
  const blocked = getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        inArray(issueDependencies.issueId, ids),
      ),
    )
    .run();
  const blocking = getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        inArray(issueDependencies.blockerId, ids),
      ),
    )
    .run();
  return blocked.changes + blocking.changes;
}

