/**
 * "Blocked by" links between issues: recording and removing them, the
 * completion gate `IssueService` consults, and the `issue_unblocked`
 * notification sent when an issue's last open blocker closes.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { isArchived, assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { notify } from "./notification-service";
import { issueResource, requireFound } from "./_support";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import type { Actor } from "@/types/member";

type BlockerInput = { orgId: OrgId; issueId: IssueId; blockerId: IssueId };

/** Raised when an issue with open blockers is moved to `done`. */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: IssueId,
    readonly blockerIds: readonly IssueId[],
  ) {
    super(
      `Issue ${issueId} is blocked by open issue(s) ${blockerIds.join(", ")}`,
    );
    this.name = "IssueBlockedError";
  }
}

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/** Open = live and neither `done` nor `canceled`. */
function isOpen(issue: Issue): boolean {
  return !isArchived(issue) && !isClosedStatus(issue.status);
}

/**
 * Records "`issueId` is blocked by `blockerId`". Re-adding an existing link
 * returns it unchanged; self-links and links that would close a cycle are
 * rejected before anything is written.
 */
export async function addBlocker(
  actor: Actor,
  input: BlockerInput,
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  if (issue.id === blocker.id) {
    throw new Error(`Issue ${issue.id} cannot block itself`);
  }

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    issue.id,
    blocker.id,
  );
  if (existing) return existing;

  if (await isBlockedTransitively(input.orgId, blocker.id, issue.id)) {
    throw new Error(
      `Issue ${blocker.id} already depends on ${issue.id}; the link would create a cycle`,
    );
  }

  return dependencyRepo.insertDependency(
    input.orgId,
    issue.id,
    blocker.id,
    actor.userId,
  );
}

/** Deletes the link; `false` when there was none. Never notifies. */
export async function removeBlocker(
  actor: Actor,
  input: BlockerInput,
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  return dependencyRepo.deleteDependency(input.orgId, issue.id, input.blockerId);
}

/** Live blockers of `issueId`, open or closed, by issue number. */
export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return dependencyRepo.listBlockerIssues(orgId, issue.id);
}

/**
 * The completion gate: throws `IssueBlockedError` when moving `issueId` to
 * `status` would complete it while an open blocker remains.
 */
export async function assertCanTransition(
  orgId: OrgId,
  issueId: IssueId,
  status: IssueStatus,
): Promise<void> {
  if (status !== "done") return;

  const open = await dependencyRepo.listBlockerIssues(orgId, issueId, {
    openOnly: true,
  });
  if (open.length > 0) {
    throw new IssueBlockedError(
      issueId,
      open.map((blocker) => blocker.id),
    );
  }
}

/**
 * Called once per blocker that just went from open to closed: every issue it
 * blocks that is itself still open, assigned, and now free of open blockers
 * gets one `issue_unblocked` notification for its assignee.
 */
export async function notifyUnblockedDependents(
  orgId: OrgId,
  blockerIds: readonly IssueId[],
  actorId: UserId | null,
): Promise<void> {
  const candidates = new Set<IssueId>();
  for (const blockerId of blockerIds) {
    for (const issueId of await dependencyRepo.listBlockedIds(
      orgId,
      blockerId,
    )) {
      candidates.add(issueId);
    }
  }

  for (const issueId of candidates) {
    const issue = await issueRepo.findIssueById(orgId, issueId);
    if (!issue || !isOpen(issue) || issue.assigneeId === null) continue;

    const open = await dependencyRepo.listBlockerIssues(orgId, issue.id, {
      openOnly: true,
    });
    if (open.length > 0) continue;

    await notify(orgId, "issue_unblocked", [issue.assigneeId], {
      title: "An issue you own is unblocked",
      body: `Every issue blocking "${issue.title}" is now closed`,
      href: `/issues/${issue.id}`,
      actorId,
    });
  }
}

/** Wired from `event-registry`; reacts to blockers closing or being archived. */
export function registerIssueDependencyListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
      await notifyUnblockedDependents(
        payload.orgId,
        [payload.issueId],
        payload.actorId,
      );
    }),
    subscribe("issue.archived", async (payload) => {
      // Archiving leaves the status alone, so the stored status is the one
      // the blocker had while it was still live.
      const issue = await issueRepo.findIssueById(
        payload.orgId,
        payload.issueId,
      );
      if (!issue || isClosedStatus(issue.status)) return;
      await notifyUnblockedDependents(
        payload.orgId,
        [payload.issueId],
        payload.actorId,
      );
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

/**
 * True when `from` is — directly or through any chain of links — blocked by
 * `target`. Adding "`target` blocked by `from`" would then close a cycle.
 */
async function isBlockedTransitively(
  orgId: OrgId,
  from: IssueId,
  target: IssueId,
): Promise<boolean> {
  const seen = new Set<IssueId>([from]);
  const queue: IssueId[] = [from];

  while (queue.length > 0) {
    const current = queue.shift() as IssueId;
    for (const blockerId of await dependencyRepo.listBlockerIds(
      orgId,
      current,
    )) {
      if (blockerId === target) return true;
      if (!seen.has(blockerId)) {
        seen.add(blockerId);
        queue.push(blockerId);
      }
    }
  }

  return false;
}

