      issueId,
      open.map((blocker) => blocker.id),
    );
  }
}

/**
 * Called once per blocker that just went from open to closed: every issue it
 * blocks that is itself still open, assigned, and now free of open blockers
 * gets one `issue_unblocked` notification for its assignee.
 */
export async function notifyUnblockedDependents(
  orgId: OrgId,
  blockerIds: readonly IssueId[],
  actorId: UserId | null,
): Promise<void> {
  const candidates = new Set<IssueId>();
  for (const blockerId of blockerIds) {
    for (const issueId of await dependencyRepo.listBlockedIds(
      orgId,
      blockerId,
    )) {
      candidates.add(issueId);
    }
  }

  for (const issueId of candidates) {
    const issue = await issueRepo.findIssueById(orgId, issueId);
    if (!issue || !isOpen(issue) || issue.assigneeId === null) continue;

    const open = await dependencyRepo.listBlockerIssues(orgId, issue.id, {
      openOnly: true,
    });
    if (open.length > 0) continue;

    await notify(orgId, "issue_unblocked", [issue.assigneeId], {
      title: "An issue you own is unblocked",
      body: `Every issue blocking "${issue.title}" is now closed`,
      href: `/issues/${issue.id}`,
      actorId,
    });
  }
}

/** Wired from `event-registry`; reacts to blockers closing or being archived. */
export function registerIssueDependencyListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
      await notifyUnblockedDependents(
        payload.orgId,
        [payload.issueId],
        payload.actorId,
      );
    }),
    subscribe("issue.archived", async (payload) => {
      // Archiving leaves the status alone, so the stored status is the one
      // the blocker had while it was still live.
      const issue = await issueRepo.findIssueById(
        payload.orgId,
        payload.issueId,
      );
      if (!issue || isClosedStatus(issue.status)) return;
      await notifyUnblockedDependents(
        payload.orgId,
        [payload.issueId],
        payload.actorId,
      );
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

/**
 * True when `from` is — directly or through any chain of links — blocked by
 * `target`. Adding "`target` blocked by `from`" would then close a cycle.
 */
async function isBlockedTransitively(
  orgId: OrgId,
  from: IssueId,
  target: IssueId,
): Promise<boolean> {
  const seen = new Set<IssueId>([from]);
  const queue: IssueId[] = [from];

  while (queue.length > 0) {
    const current = queue.shift() as IssueId;
    for (const blockerId of await dependencyRepo.listBlockerIds(
      orgId,
      current,
    )) {
      if (blockerId === target) return true;
      if (!seen.has(blockerId)) {
        seen.add(blockerId);
        queue.push(blockerId);
      }
    }
  }

  return false;
}

