import { afterAll, beforeAll, describe, expect, it } from "vitest";
import * as issueService from "$P/src/server/services/issue-service";
import * as projectService from "$P/src/server/services/project-service";
import * as dep from "$P/src/server/services/issue-dependency-service";
import { registerEventHandlers } from "$P/src/server/services/event-registry";
import { listNotifications, updatePreference } from "$P/src/server/services/notification-service";
import { updateNotificationPreferenceSchema } from "$P/src/schemas/notification";
import { createTenant, issueInput, useTemporaryDatabase } from "$P/tests/server/_support/fixtures";

let cleanup: () => void;
let t: any; let o: any;
beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  t = await createTenant("dep", "growth");
  o = await createTenant("other", "growth");
  registerEventHandlers();
});
afterAll(() => cleanup());

const notes = async (uid: any) => (await listNotifications(t.actors.owner, { orgId: t.org.id, recipientId: uid, unreadOnly: false, kind: ["issue_unblocked"], limit: 50, cursor: null })).items;

describe("deps", () => {
  it("flow", async () => {
    const mk = (title: string, assigneeId: any = null) => issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id, { title, assigneeId }));
    const a = await mk("Issue A", t.userIds.member);
    const b = await mk("Issue B");
    const c = await mk("Issue C");
    const link = await dep.addBlocker(t.actors.admin, { orgId: t.org.id, issueId: a.id, blockerId: b.id });
    expect(link.createdBy).toBe(t.userIds.admin);
    const again = await dep.addBlocker(t.actors.admin, { orgId: t.org.id, issueId: a.id, blockerId: b.id });
    expect(again).toEqual(link);
    await dep.addBlocker(t.actors.admin, { orgId: t.org.id, issueId: a.id, blockerId: c.id });
    await expect(dep.addBlocker(t.actors.admin, { orgId: t.org.id, issueId: b.id, blockerId: a.id })).rejects.toThrow();
    await expect(dep.addBlocker(t.actors.admin, { orgId: t.org.id, issueId: a.id, blockerId: a.id })).rejects.toThrow();
    const d = await mk("Issue D");
    await dep.addBlocker(t.actors.admin, { orgId: t.org.id, issueId: b.id, blockerId: d.id });
    await expect(dep.addBlocker(t.actors.admin, { orgId: t.org.id, issueId: d.id, blockerId: a.id })).rejects.toThrow(/cycle/);
    await expect(dep.addBlocker(t.actors.viewer, { orgId: t.org.id, issueId: c.id, blockerId: d.id })).rejects.toThrow();
    await expect(dep.addBlocker(t.actors.admin, { orgId: o.org.id, issueId: c.id, blockerId: d.id })).rejects.toThrow(/Tenant/);
    const ox = await issueService.createIssue(o.actors.owner, issueInput(o.org.id, o.project.id, {}));
    await expect(dep.addBlocker(t.actors.admin, { orgId: t.org.id, issueId: c.id, blockerId: ox.id })).rejects.toMatchObject({ code: "not_found" });
    expect((await dep.listBlockers(t.actors.viewer, t.org.id, a.id)).map((i) => i.title)).toEqual(["Issue B", "Issue C"]);

    await expect(issueService.moveIssue(t.actors.owner, { orgId: t.org.id, issueId: a.id, toStatus: "done", toIndex: 0 })).rejects.toMatchObject({ code: "conflict", blockerIds: [b.id, c.id] });
    await issueService.changeIssueStatus(t.actors.owner, { orgId: t.org.id, issueId: a.id, status: "in_progress" });
    await issueService.changeIssueStatus(t.actors.owner, { orgId: t.org.id, issueId: b.id, status: "done" });
    expect(await notes(t.userIds.member)).toHaveLength(0);
    await issueService.archiveIssue(t.actors.owner, t.org.id, c.id);
    let n = await notes(t.userIds.member);
    expect(n).toHaveLength(1);
    expect(n[0].href).toBe("/issues/" + a.id);
    expect(n[0].actorId).toBe(t.userIds.owner);
    await issueService.changeIssueStatus(t.actors.owner, { orgId: t.org.id, issueId: b.id, status: "canceled" });
    expect(await notes(t.userIds.member)).toHaveLength(1);
    await issueService.changeIssueStatus(t.actors.owner, { orgId: t.org.id, issueId: b.id, status: "todo" });
    await issueService.changeIssueStatus(t.actors.owner, { orgId: t.org.id, issueId: b.id, status: "done" });
    expect(await notes(t.userIds.member)).toHaveLength(2);
    expect(await dep.removeBlocker(t.actors.admin, { orgId: t.org.id, issueId: a.id, blockerId: b.id })).toBe(true);
    expect(await dep.removeBlocker(t.actors.admin, { orgId: t.org.id, issueId: a.id, blockerId: b.id })).toBe(false);
    await issueService.changeIssueStatus(t.actors.owner, { orgId: t.org.id, issueId: a.id, status: "done" });
    expect(updateNotificationPreferenceSchema.safeParse({ orgId: t.org.id, userId: t.userIds.member, kind: "issue_unblocked", inApp: false, email: false, digestOnly: false }).success).toBe(true);
    await updatePreference(t.actors.member, { orgId: t.org.id, userId: t.userIds.member, kind: "issue_unblocked", inApp: false, email: false, digestOnly: false });
  });
});
EOF
